integer R, C, i, j, di, dj, ni, nj, top, sz, da, db
integer g(256,256), vis(256,256), stki(65536), stkj(65536)
integer dies, ringf, dmax, d2, nclus, bigc, x, y

read(5,*) R, C
do i = 1, R {
  read(5,*) (g(i,j), j = 1, C)
}

do i = 1, R {
  do j = 1, C {
    vis(i,j) = 0
  }
}

# pass 1: count dies and find the largest d2 among dies
dies = 0
dmax = 0
do i = 1, R {
  do j = 1, C {
    if (g(i,j) != 0) {
      dies = dies + 1
      da = 2*i - R - 1
      db = 2*j - C - 1
      d2 = da*da + db*db
      if (d2 > dmax) dmax = d2
    }
  }
}

# pass 2: failing dies inside the ring 50%..100%
ringf = 0
do i = 1, R {
  do j = 1, C {
    if (g(i,j) == 2) {
      da = 2*i - R - 1
      db = 2*j - C - 1
      d2 = da*da + db*db
      if (2500*dmax <= 10000*d2) ringf = ringf + 1
    }
  }
}

# pass 3: 8-connected clusters of failing dies (iterative flood fill)
nclus = 0
bigc = 0
do i = 1, R {
  do j = 1, C {
    if (g(i,j) == 2 & vis(i,j) == 0) {
      sz = 0
      top = 1
      stki(1) = i
      stkj(1) = j
      vis(i,j) = 1
      while (top > 0) {
        x = stki(top)
        y = stkj(top)
        top = top - 1
        sz = sz + 1
        for (di = -1; di <= 1; di = di + 1) {
          for (dj = -1; dj <= 1; dj = dj + 1) {
            ni = x + di
            nj = y + dj
            if (ni >= 1 & ni <= R & nj >= 1 & nj <= C) {
              if (g(ni,nj) == 2 & vis(ni,nj) == 0) {
                vis(ni,nj) = 1
                top = top + 1
                stki(top) = ni
                stkj(top) = nj
              }
            }
          }
        }
      }
      if (sz >= 5) nclus = nclus + 1
      if (sz > bigc) bigc = sz
    }
  }
}

write(6,*) ringf, dies, nclus, bigc
end

integer g(256,256), vis(256,256), rs(65536), cs(65536)
integer nrow, ncol, i, j, dr, dc, nr, nc, ok
integer d2, d2max, ring, ndies, nclus, largest, size, top, r0, c0, dd

read(5,*) nrow, ncol
do i = 1, nrow {
  read(5,*) (g(i,j), j = 1, ncol)
}

# initialise visited flags and find dies and the largest d2
ndies = 0
d2max = 0
do i = 1, nrow {
  do j = 1, ncol {
    vis(i,j) = 0
    if (g(i,j) != 0) {
      ndies = ndies + 1
      d2 = (2*i - nrow - 1)*(2*i - nrow - 1) + (2*j - ncol - 1)*(2*j - ncol - 1)
      if (d2 > d2max) d2max = d2
    }
  }
}

# ring count: failing dies with 2500*D2 <= 10000*d2
ring = 0
do i = 1, nrow {
  do j = 1, ncol {
    if (g(i,j) == 2) {
      d2 = (2*i - nrow - 1)*(2*i - nrow - 1) + (2*j - ncol - 1)*(2*j - ncol - 1)
      if (2500*d2max <= 10000*d2) ring = ring + 1
    }
  }
}

# 8-connected clusters of failing dies (explicit stack, no recursion)
nclus = 0
largest = 0
do i = 1, nrow {
  do j = 1, ncol {
    if (g(i,j) == 2 & vis(i,j) == 0) {
      size = 0
      top = 1
      rs(1) = i
      cs(1) = j
      vis(i,j) = 1
      while (top > 0) {
        r0 = rs(top)
        c0 = cs(top)
        top = top - 1
        size = size + 1
        do dr = -1, 1 {
          do dc = -1, 1 {
            nr = r0 + dr
            nc = c0 + dc
            ok = 0
            if (nr >= 1 & nr <= nrow & nc >= 1 & nc <= ncol) ok = 1
            if (ok == 1) {
              if (g(nr,nc) == 2 & vis(nr,nc) == 0) {
                vis(nr,nc) = 1
                top = top + 1
                rs(top) = nr
                cs(top) = nc
              }
            }
          }
        }
      }
      if (size >= 5) nclus = nclus + 1
      if (size > largest) largest = size
    }
  }
}

write(6,*) ring, ndies, nclus, largest
end

