integer g(256,256), seen(256,256), sr(65536), sc(65536)
integer nrow, ncol, i, j, dr, dc, ii, jj, aa, bb, sp, sz, clus, ringc, fails, bigd, d2, a, b

read(5,*) nrow, ncol
fails = 0
bigd = 0
for (i = 1; i <= nrow; i = i + 1) {
  read(5,*) (g(i,j), j = 1, ncol)
  for (j = 1; j <= ncol; j = j + 1) {
    if (g(i,j) == 2) fails = fails + 1
    if (g(i,j) >= 1) {
      a = 2*i - nrow - 1
      b = 2*j - ncol - 1
      d2 = a*a + b*b
      if (d2 > bigd) bigd = d2
    }
  }
}

ringc = 0
for (i = 1; i <= nrow; i = i + 1) {
  for (j = 1; j <= ncol; j = j + 1) {
    if (g(i,j) == 2) {
      a = 2*i - nrow - 1
      b = 2*j - ncol - 1
      d2 = a*a + b*b
      if (10000*d2 < 900*bigd) ringc = ringc + 1
    }
  }
}

for (i = 1; i <= nrow; i = i + 1)
  for (j = 1; j <= ncol; j = j + 1)
    seen(i,j) = 0

clus = 0
for (i = 1; i <= nrow; i = i + 1) {
  for (j = 1; j <= ncol; j = j + 1) {
    if (g(i,j) == 2 & seen(i,j) == 0) {
      seen(i,j) = 1
      sp = 1
      sr(1) = i
      sc(1) = j
      sz = 0
      while (sp > 0) {
        ii = sr(sp)
        jj = sc(sp)
        sp = sp - 1
        sz = sz + 1
        for (dr = -1; dr <= 1; dr = dr + 1) {
          for (dc = -1; dc <= 1; dc = dc + 1) {
            aa = ii + dr
            bb = jj + dc
            if (aa >= 1 & aa <= nrow & bb >= 1 & bb <= ncol) {
              if (g(aa,bb) == 2 & seen(aa,bb) == 0) {
                seen(aa,bb) = 1
                sp = sp + 1
                sr(sp) = aa
                sc(sp) = bb
              }
            }
          }
        }
      }
      if (sz >= 10) clus = clus + 1
    }
  }
}

write(6,*) ringc, fails, clus
end

