for (i = 1; i <= 258; i = i + 1) {
  for (j = 1; j <= 258; j = j + 1) {
    g(i,j) = 0
  }
}
for (i = 1; i <= R; i = i + 1) {
  read(5,*) (rowv(k), k = 1, C)
  for (j = 1; j <= C; j = j + 1) {
    g(i+1,j+1) = rowv(j)
  }
}
dmax = 0
for (i = 1; i <= R; i = i + 1) {
  for (j = 1; j <= C; j = j + 1) {
    if (g(i+1,j+1) != 0) {
      x = 2*(i-1) - (R-1)
      y = 2*(j-1) - (C-1)
      dcell = x*x + y*y
      if (dcell > dmax) dmax = dcell
    }
  }
}
fails = 0
ringf = 0
edgef = 0
for (i = 1; i <= R; i = i + 1) {
  for (j = 1; j <= C; j = j + 1) {
    if (g(i+1,j+1) == 2) {
      fails = fails + 1
      x = 2*(i-1) - (R-1)
      y = 2*(j-1) - (C-1)
      dcell = x*x + y*y
      if (900*dmax <= 10000*dcell & 10000*dcell < 4900*dmax) ringf = ringf + 1
      e = 0
      for (dr = -1; dr <= 1; dr = dr + 1) {
        for (dc = -1; dc <= 1; dc = dc + 1) {
          if (!(dr == 0 & dc == 0)) {
            if (g(i+1+dr,j+1+dc) == 0) e = 1
          }
        }
      }
      if (e == 1) edgef = edgef + 1
    }
  }
}
write(6,*) fails, ringf, edgef
end

integer nrow, ncol, r, c, j, dr, dc, nr, nc, e
integer fails, ringf, edgef, d2, maxd, dr2, dc2, g(256,256)
double precision p1, p2, p3

read(5,*) nrow, ncol
do r = 1, nrow {
  read(5,*) (g(r,j), j = 1, ncol)
}

# largest squared distance over all dies (value 1 or 2)
maxd = 0
do r = 1, nrow {
  do c = 1, ncol {
    if (g(r,c) != 0) {
      dr2 = 2*r - nrow - 1
      dc2 = 2*c - ncol - 1
      d2 = dr2*dr2 + dc2*dc2
      if (d2 > maxd) maxd = d2
    }
  }
}

fails = 0
ringf = 0
edgef = 0
do r = 1, nrow {
  do c = 1, ncol {
    if (g(r,c) == 2) {
      fails = fails + 1

      dr2 = 2*r - nrow - 1
      dc2 = 2*c - ncol - 1
      d2 = dr2*dr2 + dc2*dc2
      p1 = 900d0 * maxd
      p2 = 10000d0 * d2
      p3 = 4900d0 * maxd
      if (p1 <= p2 & p2 < p3) ringf = ringf + 1

      e = 0
      do dr = -1, 1 {
        do dc = -1, 1 {
          if (dr == 0 & dc == 0) next
          nr = r + dr
          nc = c + dc
          if (nr < 1 | nr > nrow | nc < 1 | nc > ncol) {
            e = 1
          } else if (g(nr,nc) == 0) {
            e = 1
          }
        }
      }
      if (e == 1) edgef = edgef + 1
    }
  }
}

write(6,*) fails, ringf, edgef
end

integer nr, nc, r, c, rr, cc, dr, dc
integer g(256,256)
integer fails, ringf, edgef, dmax, d2, e, dr2, dc2

read(5,*) nr, nc
do r = 1, nr {
  read(5,*) (g(r,c), c = 1, nc)
}

fails = 0
ringf = 0
edgef = 0

# largest d2 over all dies
dmax = 0
for (r = 1; r <= nr; r = r + 1) {
  for (c = 1; c <= nc; c = c + 1) {
    if (g(r,c) != 0) {
      dr2 = 2*r - nr - 1
      dc2 = 2*c - nc - 1
      d2 = dr2*dr2 + dc2*dc2
      if (d2 > dmax) dmax = d2
    }
  }
}

for (r = 1; r <= nr; r = r + 1) {
  for (c = 1; c <= nc; c = c + 1) {
    if (g(r,c) == 2) {
      fails = fails + 1

      # ring test
      dr2 = 2*r - nr - 1
      dc2 = 2*c - nc - 1
      d2 = dr2*dr2 + dc2*dc2
      if (900*dmax <= 10000*d2 & 10000*d2 < 4900*dmax) ringf = ringf + 1

      # edge test: any of 8 neighbours is 0 or outside the map
      e = 0
      for (dr = -1; dr <= 1; dr = dr + 1) {
        for (dc = -1; dc <= 1; dc = dc + 1) {
          if (dr != 0 | dc != 0) {
            rr = r + dr
            cc = c + dc
            if (rr < 1 | rr > nr | cc < 1 | cc > nc) {
              e = 1
            } else {
              if (g(rr,cc) == 0) e = 1
            }
          }
        }
      }
      if (e == 1) edgef = edgef + 1
    }
  }
}

