integer nrow, ncol, r, c, a, b, d2, dmax, nfail, nedge, ncl, csize, sp
integer ring, ed, cr, cc, nr, nc, dr, dc
integer g(256,256), sr(65536), sc(65536)

read(5,*) nrow, ncol
do r = 1, nrow {
  read(5,*) (g(r,c), c = 1, ncol)
}

# largest squared distance of any die (value 1 or 2)
dmax = 0
do r = 1, nrow {
  do c = 1, ncol {
    if (g(r,c) != 0) {
      a = 2*(r-1) - (nrow-1)
      b = 2*(c-1) - (ncol-1)
      d2 = a*a + b*b
      if (d2 > dmax) dmax = d2
    }
  }
}

# ring_fails, edge_fails and fails
ring = 0
nedge = 0
nfail = 0
do r = 1, nrow {
  do c = 1, ncol {
    if (g(r,c) == 2) {
      nfail = nfail + 1
      a = 2*(r-1) - (nrow-1)
      b = 2*(c-1) - (ncol-1)
      d2 = a*a + b*b
      if (900d0*dmax <= 10000d0*d2 & 10000d0*d2 < 4900d0*dmax) ring = ring + 1
      ed = 0
      if (r == 1 | r == nrow | c == 1 | c == ncol) ed = 1
      if (ed == 0) {
        if (g(r-1,c) == 0 | g(r+1,c) == 0 | g(r,c-1) == 0 | g(r,c+1) == 0) ed = 1
      }
      if (ed == 1) nedge = nedge + 1
    }
  }
}

# 8-connected clusters of failing dies, via explicit stack flood fill
# visited failing cells are marked 3 so they are not counted twice
ncl = 0
do r = 1, nrow {
  do c = 1, ncol {
    if (g(r,c) == 2) {
      csize = 0
      sp = 1
      sr(1) = r
      sc(1) = c
      g(r,c) = 3
      while (sp > 0) {
        cr = sr(sp)
        cc = sc(sp)
        sp = sp - 1
        csize = csize + 1
        do dr = -1, 1 {
          do dc = -1, 1 {
            nr = cr + dr
            nc = cc + dc
            if (nr >= 1 & nr <= nrow & nc >= 1 & nc <= ncol) {
              if (g(nr,nc) == 2) {
                g(nr,nc) = 3
                sp = sp + 1
                sr(sp) = nr
                sc(sp) = nc
              }
            }
          }
        }
      }
      if (csize >= 10) ncl = ncl + 1
    }
  }
}

write(6,*) ring, nedge, ncl, nfail
end

